P1 = [[1 if False else 0]*11 for _ in range(11)]
# demo1 3-pattern
rows = {0:[1,3,4,5,6,7,8,9],1:[1,3,9],2:[1,3,5,6,7,9],3:[1,3,5,7,9],4:[1,3,5,7,9],5:[1,3,7,9],6:[1,3,4,5,6,7,9],7:[1,9],8:list(range(1,10)),10:list(range(11))}
for r,cs in rows.items():
 for c in cs:P1[r][c]=1
# translate -1 col for demo3 and remove two blockers; component
P3={(r,c-1) for r in range(11) for c in range(11) if P1[r][c] and c>=1}
obs={(0,6),(1,1),(4,9),(5,1),(6,8),(8,0),(8,3),(9,8),(10,5),(0,6)}
# remove all overlap
P3 -= obs
from collections import deque
start=(4,3) # Wait demo3 seed r4,c4, D1 seed c5 shifted -1 => c4. fix
start=(4,4)
seen={start}; q=deque([start])
while q:
 r,c=q.popleft()
 for v in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
  if v in P3 and v not in seen:seen.add(v);q.append(v)
print([''.join('3' if (r,c) in seen else '2' if (r,c) in obs else '.' for c in range(11)) for r in range(11)])

# demo2 coords template translate +1r, seed (5,5)
P2={(r+1,c) for r,cs in rows.items() for c in cs if 0<=r+1<11}
obs2={(0,2),(0,7),(2,10),(3,1),(3,8),(8,2),(8,10),(9,0),(10,5)}
P2-=obs2
start=(5,5); seen2={start}; q=deque([start])
while q:
 r,c=q.popleft()
 for v in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
  if v in P2 and v not in seen2:seen2.add(v);q.append(v)
print([''.join('3' if (r,c) in seen2 else '2' if (r,c) in obs2 else '.' for c in range(11)) for r in range(11)])

# target input; template P1 shift +1 row +1 col from demo1 seed (4,5) to target (5,6)
obsT={(0,10),(1,1),(1,6),(3,1),(5,3),(5,8),(8,0),(9,1),(9,10),(10,6)}
PT={(r+1,c+1) for r,cs in rows.items() for c in cs if 0<=r+1<11 and 0<=c+1<11}
PT-=obsT
start=(5,6); seenT={start}; q=deque([start])
while q:
 r,c=q.popleft()
 for v in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
  if v in PT and v not in seenT:seenT.add(v);q.append(v)
out=[[2 if (r,c) in obsT else 3 if (r,c) in seenT else 0 for c in range(11)] for r in range(11)]
print('\n'.join(' '.join(map(str,row)) for row in out))
print('connected',len(seenT),'template',len(PT))
